# ╔═╡ 8019bec9-1228-407b-9199-2fe29f26a981
md"""
> ### *Exercise 13.1* 
> Use your knowledge of the gridworld and its dynamics to determine an *exact* symbolic expression for the optimal probability of selecting the right action in Example 13.1

Example 13.1 is a gridworld with 3 non-terminal states and a terminal state at the far right.  The reward is -1 per step.  States 1 and 3 have actions left/right that move in the expected directions but state 2 reverses the directions.  We use a performance measure $J(\mathbf{\theta}) = v_{\pi_\theta}(S)$.  Given our feature representations of $\mathbf{x}(s, \text{right}) = [1, 0]^{\top}$ and $\mathbf{x}(s, \text{left}) = [0, 1]^{\top}$, we can only learn policies that are stochastic in terms of left/right action selection but do not vary between states.  Also observe that due to probability constraints $p_{\text{right}} = 1 - p_{\text{left}}$. For simplicity, we will use the notation $p \doteq p_{\text{left}}$ and the following for the three state values: $v1, v2, v3$.

$\begin{flalign}
v_1 &= p \times v_1 + (1-p) \times v_2 - 1 \tag{1} \\
v_1 (1-p) &= v_2 (1-p) - 1 \\
v_1 &= v_2 - \frac{1}{1-p} \tag{1′}\\
v_2 &= p \times v_3 + (1-p) \times v_1 - 1 \tag{2} \\
v_3 &= p \times v_2 - 1 \tag{3}\\
v_2 &= p \times [p\times v_2 - 1] +(1-p) \times v_1 - 1  \tag{substituting 3 into 2} \\
v_2(1 - p^2) &= -p +(1-p) \times v_1 - 1  \\
v_2 &= \frac{(1-p) v_1 - (1+p)}{(1+p)(1-p)} \tag{collecting terms} \\
&= \frac{(1-p) v_2 - 1 - (1+p)}{(1+p)(1-p)} \tag{using 1′} \\
&= \frac{v_2}{1+p} - \frac{2 + p}{(1+p)(1-p)} \\
v_2 \left [1 - \frac{1}{1+p} \right ] &= - \frac{2 + p}{(1+p)(1-p)} \\
v_2 \frac{1+p-1}{1+p} &= - \frac{2 + p}{(1+p)(1-p)} \\
v_2 &= - \frac{2 + p}{(1-p)p} \\
v_1 &= - \frac{2 + p}{(1-p)p} - \frac{1}{1-p} \\ 
&= \frac{-2 - p - p}{(1-p)p} \\ 
&= -\frac{2 + 2p}{(1-p)p} \\ 
v_3 &= -\frac{2 + p}{1-p} - 1\\
&= \frac{-2 - p - 1 + p}{1-p}\\
&= -\frac{3}{1-p}\\
\end{flalign}$

To summarize all the state values:

$\begin{flalign}
v_1 &= -\frac{2 + 2p}{(1-p)p} \\
v_2 &= - \frac{2 + p}{(1-p)p} \\
v_3 &= -\frac{3}{1-p}
\end{flalign}$
"""

# ╔═╡ 38e5d800-4d43-40d2-87ea-f7d4b4283dab
md"""
In order to find the p that maximizes the expected value for state 1, we should differentiate by p and set the result to 0

$\frac{\partial v_1}{\partial p} = -\frac{2p(1-p) - 2(1+p)(1 - 2p)}{p^2(1-p)^2}$

Setting this equal to 0 implies

$\begin{flalign}
p-p^2 &= 1 - 2p + p - 2p^2\\
p^2 + 2p - 1 &= 0 \\
\end{flalign}$

Using the quadratic equation, there are two solutions but since we know p has to be positive we only take that one.

$p = \frac{-2 \pm \sqrt{4 + 4}}{2} = \frac{-2 \pm 2\sqrt{2}}{2} = -1 \pm \sqrt{2} \implies p = \sqrt{2} - 1 \approx 0.41421$

So, in order to maximize the value at state 1, we have $p_{\text{left}} \approx 0.414$ and $p_{\text{right}} \approx 0.586$.  That also implies that $v_1 = -2\frac{1+p}{p(1-p)} = -2\frac{\sqrt{2}}{(\sqrt{2}-1)(2 - \sqrt{2})}= \frac{-2\sqrt{2}}{2 \sqrt{2} - 2 - 2 + \sqrt{2}} = \frac{-2 \sqrt{2}}{3\sqrt{2} - 4} \approx -11.657$
"""

# ╔═╡ b94fc99c-f439-4df2-8da3-c01718a136c4
md"""
Repeating this process for state 2 yields:

$\begin{flalign}
v_2 &= -\frac{2+p}{p(1-p)} \\
\frac{\partial v_2}{\partial p} &= -\frac{p(1-p) - (2+p)(1 - 2p)}{p^2(1-p)^2}
\end{flalign}$

Setting this equal to 0 implies

$\begin{flalign}
p - p^2 &= 2 - 4p + p - 2p^2 \\
p^2 + 4p - 2 &= 0 \\
\end{flalign}$

Using the quadratic equation and taking only the positive solution yields:

$p = \frac{-4 + \sqrt{16 + 8}}{2} = \frac{-4 + \sqrt{24}}{2} = -2 + \sqrt{6} \approx 0.4495$

So, in order to maximize the value at state 2, we have $p_{\text{left}} \approx 0.4495$ and $p_{\text{right}} \approx 0.5505$. Which is different from the value we got for state 1.  So There is a different optimal policy depending on the starting state.  It should be obvious for example that starting in the third state results in an optimial policy of choosing the right action every time.  The value functions for each state are plotted below.  The behavior of $v_3$ is not well defined at $p=0$ because for any finite $v_2$ it should be 0 but the limit approaching from the right side is -3.  This is because for $p=0$ both $v_1$ and $v_2$ are not finite and the episode never terminates.

The value of the state at this probability is: $v_2 = - \frac{2+p}{p(1-p)} = -\frac{\sqrt{6}}{(\sqrt{6}-2)(3 - \sqrt{6})} = - \frac{\sqrt{6}}{3 \sqrt{6} - 6 - 6 + 2 \sqrt{6}} = - \frac{\sqrt{6}}{5 \sqrt{6} - 12} \approx -9.9$
"""

# ╔═╡ 9c342958-1971-48ec-b919-5dfdcbc915a4
#=╠═╡
md"""
#### Change Plot Background Color $(@bind bgcolor ColorStringPicker(default = "#121212"))
"""
  ╠═╡ =#

# ╔═╡ e5faaa1b-88cb-43e2-8d04-8972b58b4bda
#=╠═╡
begin
	v1(p) = -2*(1+p)/((1-p)*p)
	v2(p) = -(p+2)/((1-p)*p)
	v3(p) = -3/(1-p)
	plist = 0.:0.001:1.
	traces = [scatter(x = plist, y = f.(1 .- plist), name = n) for (f, n) in zip([v1, v2, v3], ["V(S1)", "V(S2)", "V(S3)"])]
	plot(traces, Layout(font_color = "LightGray", plot_bgcolor = bgcolor, paper_bgcolor = "rgb(40, 40, 40)", yaxis_range = [-100, 0], xaxis_title = "probability of right action", yaxis_title = "State Value", width = 900, height = 600))
end
  ╠═╡ =#

# ╔═╡ 406638af-1e08-44d2-9ee4-97aa9294a94b
md"""
## 13.2 The Policy Gradient Theorem
"""

# ╔═╡ aa450da4-fe84-4eea-b6c4-9820b7982437
md"""
With continuous policy parametrization, we can smoothly very action selection probabilities by arbitrarily small amounts, something that was not possible with ϵ-greedy action selection.  Therefore stronger convergence guarantees are possible for policy-gradient methods than for action-value methods.

In the episodic case, assuming some particular non-random starting state $s_0$, we define the performance of a policy parametrized by *θ* as:

$\begin{align}
J(\mathbf{\theta}) \doteq v_{\pi_\mathbf{\theta}}(s_0) \tag{13.4}
\end{align}$

where $v_{\pi_\mathbf{\theta}}$ is the true value function for $\pi_\mathbf{\theta}$, the policy determined by $\mathbf{\theta}$.

The *policy gradient theorem* provides an analytic expression for the gradient of performance with respect to the policy parameter that does *not* involve the derivative of the state distribution:

$\begin{align}
\nabla J(\mathbf{\theta}) \propto \sum_s \mu (s) \sum_a q_\pi (s, a) \nabla \pi (a|s,\mathbf{\theta}) \tag{13.5}
\end{align}$

where the gradients are column vectors of partial derivatives with respect to the components of $\mathbf{\theta}$.  In the episodic case, the constant of proportionality is the average length of an episode, and in the continuing case it is 1.  The distribution here $\mu$ is the on-policy distribution under $\pi$.
"""


# ╔═╡ fdd3f4fd-4706-4d6b-b150-6ee6b4b370cb
md"""
### Notes on Probability Distributions

In order to prove the policy gradient theorem, we must manipulate terms that are probability distributions over states and visit steps.  In order to build intuition for these distributions, we can visualize how data is being averaged with the sort corridor example.  The following function simulates many episodes in the environment with a stochastic policy that has some probability of moving left regardless of the state.  The simulation keeps track of the visit count for a given state and the visit step.  The result of the accumulation is a matrix who's columns contain the number of times each state was visited on every step of an episode across all of the simulated episodes.  If we divide each count by the number of episodes simulated, then we have an unbiased sample of the expected count per episode.
"""

# ╔═╡ a0a5c163-6c35-46d1-b312-42f666bce9a3
md"""
$\eta(s) = \sum_k \eta(s, k) \mu(s, k)$
$\eta(k) = \sum_s \eta(s, k) \mu(s, k)$
$\eta = \sum_s \sum_k \eta(s, k) \mu(s, k)$
$\mathbb{E}[x] = \sum_{x \in \mathcal{X}} x \Pr\{ X = x \}$

For the expected value calculation $\sum_{x \in \mathcal{X}} \Pr \{ X = x\} = 1$

If we wan the expected number of steps of an episode for example, we need to first calculate the probability across steps which we can do by takin the univariate distribution and summing accross states.  Then we have the probability as a function of k.  Then we just sum and multiply by k when we sum over the probabilities.

$\mathbb{E}[k] = \eta = \sum_s \sum_k k \mu(s, k)$

$\eta(s) = \eta \mu(s) = \mu(s)\sum_{s^\prime}\sum_k k \mu(s^\prime, k) = \sum_{k^\prime} \mu(s, k^\prime) \sum_{s^\prime}\sum_k k \mu(s^\prime, k)= \sum_{k^\prime} \mu(s, k^\prime) \sum_k k \sum_{s^\prime} \mu(s^\prime, k) = \mu(s) \sum_k k \mu(k) = \sum_k k \mu(s) \mu(k)$
"""

# ╔═╡ f6281f84-46e6-4023-8e32-9af4aa6dbb23
md"""
We can index the above matrix with the visit step $k$ and the state $s$: $\eta(s, k)$ refers of the expected visit count of state $s$ on step $k$.  $\eta(s, k)$ can be normalized into a probability distribution in several ways.  For all of the distributions we have the condition that $\Pr \{S_0 = 1 \} = 1$ and a specific policy $\pi$ is being followed both of which are omitted in the expressions below.

Also note that $\eta(s) = \sum_k \eta(s, k)$ is the expected visits to a state during an episode and that $\eta(k) = \sum_s \eta(s, k)$ is the expected visits to a step count during an episode (this one is always less than 1) and $\sum_s \sum_k \eta(s, k) = \sum_s \eta(s) = \sum_k \eta(k) = \eta$ which is the expected number of steps in an episode.

##### Full Probability Distribution
Data is normalized across the entire visit count and each count is a separate probability.  This distribution is the most granular as it contains the probability of being in a specific state and a specific time step such that $\sum_s \sum_k \mu(s, k) = 1$: 

$\mu(s, k) = \frac{\eta(s, k)}{\sum_{x \in \mathcal{S}} \sum_{t \in \{1, 2, \dots \}} \eta(x, t)}$

##### Probability Distribution Across Steps
Data is summed across states but normalized for all visit counts.  Specifies the probability of being at a particular step regardless of the state such that $\sum_k \mu(k) = 1$: 

$\mu(k) =  \sum_s \frac{\eta(s, k)}{\sum_{k^\prime} \sum_{s^\prime} \eta(s^\prime, k^\prime)} = \sum_s \mu(s, k)$

##### Stationary State Distribution
 $\mu(s)$ is the first distribution considered and is simply the probability of being in a particular state independent of the step count such that $\sum_s \mu(s) = 1$: 

$\mu(s) = \sum_k \frac{\eta(s, k)}{\sum_{s^\prime} \sum_{k^\prime} \eta(s^\prime, k^\prime)} = \sum_k \mu(s, k)$

##### Probability Distribution Across Steps For a Single State
The same distribution across steps except instead of being for each state, data is partitioned per state and only normalized for the visit counts to that state.  The subscript on $\mu$ indicates that $s$ is fixed for the distribution rather than being a random variable and it obeys the property $\sum_k \mu_s(k) = 1$: 

$\mu_s(k) = \frac{\eta(s, k)}{\sum_{k^\prime} \eta(s, k^\prime)}$

##### Probability Distribution Across States For a Single Step
Similar to the stationary state distribution except taken on a specific time step rather than across all time steps.  The subscript on $\mu$ indicates that $k$ is fixed for the distribution rather than being a random variable and it obeys the property $\sum_s \mu_k(s) = 1$:

$\mu_k(s) = \frac{\eta(s, k)}{\sum_{s^\prime} \eta(s^\prime, k)}$

Note that $\sum_k \mu_k(s) = \eta \sum_k \frac{\mu(s, k)}{\sum_{s^\prime} \eta(s^\prime, k)}$
"""

# ╔═╡ b138572c-0d5d-49b7-81c8-6e81dd09a502
md"""
Since every episode starts in state one, the first row of the matrix only has a count for state 1 and that count equals the total number of simulations.  From there the simulations branch and distribute the visits to subsequent steps and states.  The final rows contain samples from episodes that lasted longer than all of the others and are thus lower probability events with fewer samples.  From these counts, we can form several different probability distributions depending on how we sum and normalize the data.  The plots below summarize all of the typical distributions that are of interest and also used in the earlier proof.
"""

# ╔═╡ ca360680-afc9-4dd9-9351-493643f91575
md"""
#### Probability distributions for short corridor gridworld example with probability of left action selected below
"""

# ╔═╡ 4a39f9a7-72d4-44ad-895a-742cd1291f92
#=╠═╡
@bind dist_plot_p Slider(0.1f0:0.1f0:.9f0; default = 0.5f0, show_value=true) |> confirm
  ╠═╡ =#

# ╔═╡ 37a8ef7e-e859-4ef0-81e2-76c02a324031
md"""
### Policy Gradient Theorem Proof

$\begin{flalign}
\nabla v_\pi(s) &= \nabla \left [ \sum_a \pi(a \vert s) q_\pi(s, a) \right ] \text{, } \forall s \in \mathcal{S} \tag{definitiong of value functions and expected value} \\
&= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) + \pi(a \vert s) \nabla q_\pi(s, a) \right ] \tag{product rule} \\
&= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) + \pi(a \vert s) \nabla \sum_{s^\prime, r} p(s^\prime, r \vert s, a)(r + \gamma v_\pi(s^\prime) \right ] \tag{relationship between action and state values} \\
&= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) + \pi(a \vert s) \gamma \sum_{s^\prime} p(s^\prime \vert s, a) \nabla v_\pi(s^\prime) \right ] \tag{gradient independence}\\
\end{flalign}$

Note that the final term in the sum is the original expression evaluated at $s^\prime$ instead of $s$, so we have derived a recurssive expression which can be applied repeatedly:

$\begin{flalign}
\nabla v_\pi(s) &= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) + \pi(a \vert s) \gamma \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime} \left [ \nabla \pi(a^\prime \vert s^\prime) q_\pi(s^\prime, a^\prime) + \pi(a^\prime \vert s^\prime) \gamma \sum_{s^{\prime \prime}} p(s^{\prime \prime} \vert s^\prime, a^\prime) \nabla v_\pi(s^{\prime \prime}) \right ] \right ] \tag{recur once}\\
&= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) \right ] +  \gamma \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime} \left [ \nabla \pi(a^\prime \vert s^\prime) q_\pi(s^\prime, a^\prime) \right ] \right ] + \\ &\hspace{50px} \gamma^2 \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime} \pi(a^\prime \vert s^\prime) \sum_{s^{\prime \prime}} p(s^{\prime \prime} \vert s^\prime, a^\prime) \nabla v_\pi(s^{\prime \prime}) \right ] \tag{grouping terms}\\
&= \sum_a \left [ \nabla \pi(a \vert s) q_\pi(s, a) \right ] +  \gamma \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime} \left [ \nabla \pi(a^\prime \vert s^\prime) q_\pi(s^\prime, a^\prime) \right ] \right ] + \\ &\hspace{50px} \gamma^2 \sum_a \left [ \pi(a \vert s)\sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime}  \pi(a^\prime \vert s^\prime) \sum_{s^{\prime \prime}} p(s^{\prime \prime} \vert s^\prime, a^\prime) \sum_{a^{\prime \prime}} [ \nabla \pi(a^{\prime \prime} \vert s^{\prime \prime}) q_\pi(s^{\prime \prime}, a^{\prime \prime})\right ] + \cdots \tag{extend recursion}\\
\end{flalign}$
"""

# ╔═╡ 339b4d2b-2237-46a3-9867-ecc3332856c1
md"""
This expression repeats terms of the form $\nabla \pi(a \vert s) q_\pi(s, a)$ summed over different probabilities.  The first appearance of this term is just a sum over all actions at the state $s$ which is the state we are using for the gradient expression.  The next appearance of the expression is a sum over actions at state $s^\prime$.  Let's define a new expressions: 

$\begin{flalign}
f(s) &\doteq \sum_a \nabla \pi(a \vert s) q_\pi(s, a) \\
\end{flalign}$  

Then we can rewrite the second term as follows:

$\gamma \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) f(s^\prime) \right ] = \gamma \sum_{s^\prime} \Pr (s \rightarrow s^\prime, 1, \pi) f(s^\prime)$

where the final expression uses the probability that the agent transitions from state $s$ to $s^\prime$ in one step under the policy $\pi$.  Using this same logic, we can rewrite the third expression as well.
"""

# ╔═╡ 05b0fcad-628b-48d2-aa24-f6f562dbb660
md"""
$\begin{flalign}
&\gamma^2 \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime}  \pi(a^\prime \vert s^\prime) \sum_{s^{\prime \prime}} p(s^{\prime \prime} \vert s^\prime, a^\prime) \sum_{a^{\prime \prime}} [ \nabla \pi(a^{\prime \prime} \vert s^{\prime \prime}) q_\pi(s^{\prime \prime}, a^{\prime \prime})\right ] \\
&\gamma^2 \sum_a \left [ \pi(a \vert s) \sum_{s^\prime} p(s^\prime \vert s, a) \sum_{a^\prime}  \pi(a^\prime \vert s^\prime) \sum_{s^{\prime \prime}} p(s^{\prime \prime} \vert s^\prime, a^\prime) f(s^{\prime \prime}) \right ] \\
&\gamma^2 \sum_{s^{\prime \prime}} \Pr(s \rightarrow s^{\prime \prime}, 2, \pi) f(s^{\prime \prime})
\end{flalign}$
"""

# ╔═╡ 17d07ef4-7c0a-47cc-a701-32c60336571b
md"""
Noticing this pattern, the kth term will be of the form $\gamma^k \sum_{x \in \mathcal{S}} \Pr(s \rightarrow x, k, \pi)f(x)$ and the total expression will just be a sum of all of these terms to infinity or the maximum length of an episode under the policy.  Note that these probabilities satisfy the property $\sum_x \Pr(s \rightarrow x, k, \pi) = 1$ for a specific $s, k, \pi$ and also that $\sum_k \Pr(s_0 \rightarrow s, k, \pi) = \eta(s)$ which is the expected number of visits to a state $s$ under the policy $\pi$ starting from state $s_0$.  What if we wanted to calculate the expected time step we would visit a specific state $s$, that is if we sampled from trajectories starting from state $s_0$ and every time we encountered a state $s$ we took note of what time step it was.  Over multiple episodes, the time steps would appear with a frequency that matched the probability distribution of $k$ where $k$ is the time step on which we visit state $s$.  We know that over all $k$, the probability we have is not normalized, so to get this type of probability we would need to normalize it with the denominator: $\Pr(k = t \mid s_0 \rightarrow s, k, \pi) = \frac{\Pr(s_0 \rightarrow s, k, \pi)}{\sum_{k^\prime} \Pr(s_0 \rightarrow s, k, \pi)}$ where this distribution is normalized over all $k$ for a given $s$ and the probabilities in the fraction are normalized over all states $s$ for a given $k$.  Using the notation introduced above, we can rewrite this probabilities more compactly as $\Pr \{ s_0 \rightarrow s, k, \pi \} = \mu_k(s)$ and $\Pr \{k = t \mid s_0 \rightarrow s, k, \pi \} = \mu(s, t) = \frac{\mu_t(s)}{\sum_k \mu_k(s)}$.  Also we have $\sum_k \mu_k(s) = \eta(s)$
"""

# ╔═╡ 2a586e46-66e4-461a-85c8-5817e4d1aa43
md"""
$\begin{flalign}
\nabla J(\mathbf{\theta}) &= \nabla v_\pi(s_0) \\
&= \sum_s \sum_k \gamma^k \Pr \{ s_0 \rightarrow s, k, \pi \} f(s) \\
&= \sum_s f(s) \sum_k \gamma^k \mu_k(s) \\
&= \sum_s f(s) \frac{\sum_{k^\prime}\mu_{k^\prime}(s)}{\sum_{k^\prime} \mu_{k^\prime}(s)} \sum_k \gamma^k \mu_k(s) \tag{multiply by 1}\\
&= \sum_s f(s) \sum_{k^\prime} \mu_{k^\prime}(s) \sum_k \gamma^k \frac{\mu_k(s)}{\sum_{k^\prime} \mu_{k^\prime}(s)}\\
&= \sum_s f(s) \eta(s) \sum_k \gamma^k \mu(s, k)\\
&= \sum_s f(s) \frac{\sum_{s^\prime} \eta(s^\prime)}{\sum_{s^\prime} \eta(s^\prime)} \eta(s) \sum_k \gamma^k \mu(s, k) \tag{multiply by 1}\\
&= \sum_{s^\prime} \eta(s^\prime) \sum_s f(s)  \frac{\eta(s)}{\sum_{s^\prime} \eta(s^\prime)} \sum_k \gamma^k \mu(s, k) \\
&= \sum_{s^\prime} \eta(s^\prime) \sum_s f(s)  \mu(s) \sum_k \gamma^k \mu(s, k) \tag{state distribution}\\
&\propto \sum_s f(s)  \mu(s) \sum_k \gamma^k \mu(s, k) \tag{constant value per state}\\
&= \sum_s f(s) \mu(s) \sum_k \gamma^k \mu(s, k) \frac{\sum_{s^\prime} \mu(s^\prime, k)}{\sum_{s^\prime} \mu(s^\prime, k)} \tag{multiply by 1}\\
&= \sum_s f(s) \mu(s) \sum_k \gamma^k \mu_s(k) \mu(k) \\
&= \mathbb{E}_\pi \left [ f(s) \sum_k \gamma^k \mu(s, k) \right ] \\
&= \sum_s f(s) \sum_{k^\prime} \mu(s, k^\prime) \sum_k \gamma^k \mu_k(s) \tag{renormalize distribution}\\
&= \sum_s f(s) \mu(s) \mathbb{E}_\pi[ \gamma^k \mid S_0 = s_0, S_k = s] \\
&= \mathbb{E}_\pi \left [ \gamma^k \sum_a \nabla \pi(a \vert s) q_\pi(s, a) \mid S_0 = s_0, S_k = s \right ] \\
\end{flalign}$
"""

# ╔═╡ 8eab8297-229c-4493-8c2a-956aea4416fb


# ╔═╡ f924eb30-d1cc-4941-8fb5-ff70ad425ab9
md"""
## 13.3 REINFORCE: Monte Carlo Policy Gradient

If we replace the true action-value function in (13.5) with a learned approximation $\hat q_\pi$, then we have a method called the *all-actions* method because the update involves the sum over all actions.  For the REINFORCE algorithm, we instead sample this value using the actual return and the policy distribution.

We can re-write (13.5) using an expected value under the policy and continue from there:

$\begin{flalign}
\nabla J(\mathbf{\theta}) & \propto \mathbb{E}_\pi \left [ \gamma^t \sum_a q_\pi (S_t, a) \nabla \pi(a|S_t, \mathbf{\theta}) \right ] \tag{13.6}\\
 &= \mathbb{E}_\pi \left [\gamma^t \sum_a \pi(a|S_t, \mathbf{\theta}) q_\pi (S_t, a) \frac{\nabla \pi(a|S_t, \mathbf{\theta})}{\pi(a|S_t, \mathbf{\theta})} \right ] \tag{multiply and divide by policy} \\
 &= \mathbb{E}_\pi \left [ \gamma^t q_\pi (S_t, A_t) \frac{\nabla \pi(A_t|S_t, \mathbf{\theta})}{\pi(A_t|S_t, \mathbf{\theta})} \right ] \tag{replace a with sample under policy} \\
 &= \mathbb{E}_\pi \left [ \gamma^t G_t \frac{\nabla \pi(A_t|S_t, \mathbf{\theta})}{\pi(A_t|S_t, \mathbf{\theta})} \right ] \tag{replace value with sample return} \\
\end{flalign}$

Using the expression in the brackets we can write down an update rule for the parameters that can be sampled on each time step.  This is the **REINFORCE update**:

$\begin{align}
\mathbf{\theta}_{t+1} \doteq \mathbf{\theta}_t + \alpha \gamma^t G_t \frac{\nabla \pi(A_t|S_t, \mathbf{\theta}_t)}{\pi(A_t|S_t, \mathbf{\theta}_t)} \tag{13.8}
\end{align}$

Because it uses all future returns after step t, REINFORCE is a Monte Carlo algorithm and is well defined only for the episodic case.  For implementation purposes we can replace $\frac{\nabla \pi(A_t|S_t, \mathbf{\theta})}{\pi(A_t|S_t, \mathbf{\theta})}$ with $\nabla \ln \pi(A_t|S_t, \mathbf{\theta}_t)$ which is usually refered to as the *eligibility vector*.

With the alternative parameterization, the eligibility vector is $\nabla \ln \pi(S_t, \theta_t)_{A_t}$ where $\pi$ is a vector and the $A_t$ subscript takes the value of that vector at the index corresponding to the action $A_t$.
"""

# ╔═╡ 189798b3-ec6b-48b9-918c-ee0f65935ab3
md"""
> ### *Exercise 13.3* 
> In Section 13.1 we considered policy parameterizations using the soft-max in action preferences (13.2) with linear action preferences (13.3).  For this parameterization, prove that the eligibility vector is
> $\begin{flalign}
> 	\nabla \ln \pi(a|s, \mathbf{\theta}) = \mathbf{x}(s, a) - \sum_b \pi(b|s, \mathbf{\theta}) \mathbf{x}(s, b) \tag{13.9}
> \end{flalign}$
> using the definitions and elementary calculus.
"""

# ╔═╡ 70096b14-beab-4f71-9886-6355c749bb8a
md"""
We previously derived an expression for the gradient of the policy itself in the case of linear action preferences:

$\begin{flalign}
h_a &= \theta^\top \mathbf{x}(s, a) \\
\pi_a &= \frac{e^{h_a}}{\sum_k e^{h_k}} \\
\nabla(\pi_a)_i &= \pi_a \left ( \mathbf{x}(s, a)_i - \sum_k \pi_k \mathbf{x}(s, k)_i \right)
\end{flalign}$ 

Applying the chain rule to the natural logarithm produces: 

$\nabla \left ( \ln f(\theta) \right) = \frac{\nabla f(\theta)}{f(\theta)} \implies \nabla \left ( \ln f(\theta) \right )_i = \frac{\nabla \left ( f(\theta) \right )_i}{f(\theta)}$

Applying this to the above expression yields:

$\begin{flalign}
\nabla \left ( \ln \pi_a \right )_i &= \frac{\nabla \left ( \pi_a \right )_i}{\pi_a} \\
&= \frac{\pi_a \left ( \mathbf{x}(s, a)_i - \sum_k \pi_k \mathbf{x}(s, k)_i \right)}{\pi_a} \\
&= \mathbf{x}(s, a)_i - \sum_k \pi_k \mathbf{x}(s, k)_i
\end{flalign}$

which is the per component version of the desired vector expression.
"""

# ╔═╡ 1558cec1-c4fd-4bc0-85ed-ae22c6067d41
md"""
We can also repeat this derivation for the alternative linear parameterization where we only have state feature vectors and a parameter matrix with components $\mathbf{\theta}_{i, j}$:

$\begin{flalign}
\mathbf{h} &= \theta^\top \mathbf{x}(s) \\
h_a &= \mathbf{h}_a \\
\mathbf{\pi}(s) &= \sigma(\mathbf{h}) \\
\pi_a &= \sigma(\mathbf{h})_a \\
\nabla(\pi_a)_{i, j} &= \pi_a \begin{cases}
\mathbf{x}(s)_i (1 - \pi_j), & \text{ if } j = a \\
-\pi_j \mathbf{x}(s)_i, & \text{ else }\\
\end{cases}
\end{flalign}$ 

We already know how to apply the chain rule to the natural logarithm so our final gradient is:

Applying this to the above expression yields:

$\begin{flalign}
\nabla \left ( \ln \pi_a \right )_{i, j} &= \frac{\nabla \left ( \pi_a \right )_{i, j}}{\pi_a} \\
&= \begin{cases}
\mathbf{x}(s)_i (1 - \pi_j), & \text{ if } j = a \\
-\pi_j \mathbf{x}(s)_i, & \text{ else }\\
\end{cases}
\end{flalign}$

which is the per component version of the desired vector expression.
"""

# ╔═╡ e3a2fb12-37ce-4c23-ad93-5fc89991aabb
md"""
### Eligibility Vector for General Soft-Max and State Feature Vector
"""

# ╔═╡ 58403c8e-0ee4-4466-ba25-ee0c86fb0b47
md"""
Consider $\mathbf{x}(s)$ and $\mathbf{h}(s, \theta)$ which produces a vector of action preferences.  We would like to derive an expression for $\nabla \ln \pi (a \vert s, \theta)$ in the case of $\mathbf{\pi}(s, \theta) = \sigma(\mathbf{h}(s, \theta))$ where $\sigma(\mathbf{x})$ is the softmax function defined in section 13.1.  Here I'm using the notation $\mathbf{\pi}(s, \theta)$ to refer to the vector of action probabilities at a given state.  The subscript on the vector refers to selecting that element from the vector.  To shorten expressions, the following terms are equivalent:

$\begin{flalign}
\mathbf{\pi} &\doteq \mathbf{\pi}(s, \theta) \\
\mathbf{h} &\doteq \mathbf{h}(s, \theta) \\
x_i &\doteq \mathbf{x}_i \text{ for all vectors} \\ 
\end{flalign}$

Using these conventions, we previously had an expression for the ith component of the gradient of the policy:

$\nabla \left( \pi_a \right )_i = \pi_a \left ( \frac{\partial{h_a}}{\partial{\theta_i}}  - \sum_k{\pi_k \frac{\partial{h_k}}{\partial{\theta_i}}} \right )$

We can use this expression to derive the components of the eligibility vector in general:

$\begin{flalign}
\nabla \left( \ln \mathbf{\pi}_a \right)_i &= \frac{\nabla \left( \pi_a \right )_i}{\pi_a}\\
&=\frac{\partial{h_a}}{\partial{\theta_i}}  - \sum_k{\pi_k \frac{\partial{h_k}}{\partial{\theta_i}}} \\
\end{flalign}$

### Connection to Cross-Entropy Loss
Classification problems involve training a function to predict the class label of an input.  The function returns a vector of class preferences which can be converted to a probability distribution by the soft-max function.  The cross-entropy loss is a way of comparing this distribution with the desired output label to generate an error value.  

Let's denote $\mathbf{p}(s)$ as the vector of true probabilities for an example $s$ and keep our output function as $\pi(s,\theta) = \sigma(\mathbf{h}(s, \theta))$.  The cross entropy loss is defined as: 

$\mathcal{L}(\mathbf{p}, \mathbf{\pi}) = -\sum_i \mathbf{p}_i \ln \mathbf{\pi}_i$ omitting $s$ and $\theta$.  

In a typical situation with a dataset, $\mathbf{p}(s)$ will be a one-hot vector representing the index of label of the example in the dataset.  Let's call that index $a$ such that $p_a = 1$ and $p_i = 0 \: \forall i \neq a$.  The loss then simplifies to $\mathcal{L}(a, \mathbf{\pi}) = -\ln \mathbf{\pi}_a$.  When we train with gradient descent on such a dataset, we must compute the gradient of this loss with respect to the parameters or $-\nabla \ln \pi_a$ which is just negative one times the eligibility vector for general paramaterized approximation.  So if we have a function that computes the gradient of the cross entropy loss of the soft-max output for a vector function and a label index, we can replace the label index of the dataset with the desired action index $a$ and then that gradient will match our desired gradient after multiplying by negative one. 
"""

# ╔═╡ 73b90260-d57a-449a-8db6-47f91e6a4e4f
md"""
### Eligibility Vector with Binary Features
"""

# ╔═╡ ee72af8d-3cb8-4314-82df-580f068e1252
md"""
One common form of linear feature vector is one that selects active features per state.  Tile coding is an example of this where a state is assigned a tile in each tiling used and the number of tilings control how many active features a given state will have.  Because the only possible feature vector values are 1 or 0, this style of encoding need not be as complex as other methods.  We can see by the form of the gradients an abbreviated algorithm that need not compute the eligibility vector explicitely.

We can define a binary feature encoding by the function $\mathcal{F}(s)$ which returns the indices of active features for a state $s$ as well as the knowledge of how many total features there are, $d$.  All of the values of $\mathbf{x}(s)$ are zero except for the indices in $\mathcal{F}(s)$ whose values are 1.  That simplifies the expression we have before for the linear feature eligibility vector:

$\begin{flalign}
\nabla \left ( \ln \pi_a \right )_{i, j} &= \frac{\nabla \left ( \pi_a \right )_{i, j}}{\pi_a} \\
&= \begin{cases}
\mathbf{x}(s)_i (1 - \pi_j), & \text{ if } j = a \\
-\pi_j \mathbf{x}(s)_i, & \text{ else }\\
\end{cases} \\
&= \begin{cases}
(1 - \pi_j), & \text{ if } j = a \text{, } i \in \mathcal{F}(s) \\
-\pi_j, & \text{ if } j \neq a \text{, } i \in \mathcal{F}(s) \\
0, & \text{ otherwise}
\end{cases}
\end{flalign}$

We can see from this form of the eligibility vector that it need not be computed explicitely and we do not need to instantiate a feature vector either.  Rather we can simply go through the active feature indices and subtract the policy output for the column index at each row and then add 1 to the column corresponding to the selected action:

Loop for each step of the episode $t = 0, 1, \cdots, T-1$

$G \leftarrow \sum_{k=t+1} \gamma^{k-t-1}R_k$

$c = \alpha \times \gamma^t \times G$

Loop for each action index j 

Loop for each feature i

$\theta_{i, j} \leftarrow \theta_{i, j} - c \times \pi(a_j, S_t, \mathbf{\theta})$

Define $j_a$ as the column index corresponding to action $A_t$
Loop for each feature i

$\theta_{i, j_a} \leftarrow \theta_{i, j_a} + c$

Specialized versions of REINFORCE that use binary features and linear features can be found below as well as the general case that works for any type of parameterized function approximation.
"""

# ╔═╡ 89901156-b874-416b-89c1-6dc434a4eb17
md"""
### *REINFORCE Implementation*
"""

# ╔═╡ 5c11a92d-7496-4aba-af15-2537eac49dd7
const FCANNActivations{T} = Vector{Vector{T}} where T<:Real 

# ╔═╡ 581f7e9b-a5c2-4841-9605-85f9585b0274
update_linear_action_preferences!(action_preferences::Vector{T}, x::Vector{T}, params::Matrix{T}) where T<:AbstractFloat = BLAS.gemv!('T', one(T), params, x, zero(T), action_preferences)

# ╔═╡ da2d3186-a778-41cc-9b49-759bf1e9b8fa
const BinaryFeatures{I} = Union{C1, C2, C3} where {I <: Integer, C1 <: AbstractVector{I}, N, C2 <: NTuple{N, I}, T<:AbstractVector{I}, C3 <: Base.Generator{T}}

# ╔═╡ f92bb265-4b19-4f0e-a698-d7547bb6dd41
mutable struct BinaryFeatureVector{I <: Integer}
	active_features::Vector{I}
	num_features::I
	function BinaryFeatureVector()
		new{Int64}(Vector{Int64}(), 0)
	end
end

# ╔═╡ 8eab55a5-41b7-4f5e-a02f-4c19388bc9ea
function update_binary_feature_vector!(x::BinaryFeatureVector, s::S, get_active_features::Function) where S
	active_features = get_active_features(s)
	l = length(x.active_features)
	n = 0
	for (i, f) in enumerate(active_features)
		if i > l 
			push!(x.active_features, f)
		else
			x.active_features[i] = f
		end
		n += 1
	end
	x.num_features = n
	return x
end

# ╔═╡ a361f4c9-47ce-42ad-899c-87b611c0d471
function update_binary_action_preferences!(action_preferences::Vector{T}, binary_features::BinaryFeatureVector, params::Matrix{T}) where T<:Real
	@inbounds for i_a in eachindex(action_preferences)
		action_preferences[i_a] = zero(T)
		@simd for i in 1:binary_features.num_features
			j = binary_features.active_features[i]
			action_preferences[i_a] += params[j, i_a]
		end
	end
	return action_preferences
end

# ╔═╡ cc3ac95e-a398-438a-ba3d-62b6733f6342
function update_fcann_action_preferences!(action_preferences::Vector{T}, x::Vector{T}, params::FCANNParams, activations::FCANNActivations{T}, reslayers::Integer) where T<:Float32
	FCANN.forwardNOGRAD_base!(activations, params..., x, reslayers)
	action_preferences .= activations[end]
end

# ╔═╡ 4634267b-5dea-4164-8bb2-1eb2fd4d7954
function update_linear_eligibility_vector!(∇lnπ::Matrix{T}, action_preferences::Vector{T}, x::Vector{T}, i_a::Integer, params::Matrix{T}) where T<:AbstractFloat
	update_linear_action_preferences!(action_preferences, x, params)
	soft_max!(action_preferences)
	BLAS.gemm!('N', 'T', -one(T), x, action_preferences, zero(T), ∇lnπ)
	@inbounds @simd for i in eachindex(x)
		∇lnπ[i, i_a] += x[i]
	end
end

# ╔═╡ 45f0a385-6465-4acc-8637-1b007a0fe215
function update_fcann_eligibility_vector!(∇lnπ::FCANNParams, action_preferences::Vector{T}, x::Vector{T}, i_a::Integer, params::FCANNParams, hidden_layers, l2, tanh_grad_z, activations, deltas, dropout, reslayers, activation_list, scales) where T<:Float32
	FCANN.nnCostFunction(params..., hidden_layers, x, i_a, l2, ∇lnπ..., tanh_grad_z, activations, deltas, dropout; resLayers = reslayers, loss_type = CrossEntropyLoss(), activation_list = activation_list)
	@inbounds for i in eachindex(params[1])
		for j in 1:2
			∇lnπ[j][i] .*= -1f0 * scales[i]
		end
	end
end

# ╔═╡ 41dc149d-c6f3-4b0d-a856-06f3aaae3049
mutable struct BinaryEligibilityVector{T, B <: BinaryFeatureVector}
	binary_features::B
	i_a::Int64
	π_dist::Vector{T}
end

# ╔═╡ b0a66a19-ee76-463b-a704-8fcee85444d0
begin
	function update_params_with_gradient!(θ::Array{T, N}, α::T, ∇θ::Array{T, N}) where {T<:Real, N}
		θ .+= α .* ∇θ
	end

	function update_params_with_gradient!(θ::Matrix{T}, α::T, ∇θ::BinaryEligibilityVector{T, B}) where {T<:Real, B<:BinaryFeatureVector}
		@inbounds for i in eachindex(∇θ.π_dist)
			@simd for j in 1:∇θ.binary_features.num_features
				k = ∇θ.binary_features.active_features[j]
				θ[k, i] -= α*∇θ.π_dist[i]
			end
		end
		
		@inbounds @simd for i in 1:∇θ.binary_features.num_features
			j = ∇θ.binary_features.active_features[i]
			θ[j, ∇θ.i_a] += α
		end
		return θ
	end

	function update_params_with_gradient!(params::FCANNParams{T}, α::T, ∇::FCANNParams{T}) where T<:Float32
		for i in eachindex(first(params))
			for j in 1:2
				# @info "updating parameter $((j, i)) $(params[j][i]) with gradient $(∇[j][i]) and constant $α"
				update_params_with_gradient!(params[j][i], α, ∇[j][i])
				# @info "new parameter values are:  $(params[j][i])"
			end
		end
	end

	update_params_with_gradient!(::Nothing, α::T, ::Nothing) where T<:Real = return nothing
end

# ╔═╡ 042fbafe-2401-4fb7-ac13-4531e0782c79
function update_binary_eligibility_vector!(∇lnπ::BinaryEligibilityVector{T, B}, action_preferences::Vector{T}, binary_features::B, i_a::Integer, params::Matrix{T}) where {T<:Real, B<:BinaryFeatureVector}
	update_binary_action_preferences!(action_preferences, binary_features, params)
	soft_max!(action_preferences)
	∇lnπ.binary_features = binary_features
	∇lnπ.i_a = i_a
	∇lnπ.π_dist .= action_preferences
	return ∇lnπ
end

# ╔═╡ 65d2add6-fd6f-456c-92ed-3cd9d1862ef6
function update_binary_policy_params!(params::Matrix{T}, active_features::BinaryFeatures, i_a::Integer, π_dist::Vector{T}, c::T) where T<:Real
	@inbounds for i in eachindex(π_dist)
		for j in active_features
			params[j, i] -= c*π_dist[i]
		end
	end
	
	@inbounds for j in active_features
		params[j, i_a] += c
	end
	return params
end

# ╔═╡ 96506201-6b66-49e6-8179-06952e2394e1
function setup_binary_policy_arguments(mdp::StateMDP{T, S, A, P, F1, F2, F3}, get_active_features::Function, num_features::Integer) where {T<:Real, S, A, P, F1, F2, F3} 
	x = BinaryFeatureVector()
	update_feature_vector!(x::BinaryFeatureVector, s) = update_binary_feature_vector!(x, s, get_active_features)
	action_preferences = zeros(T, length(mdp.actions))
	∇lnπ = BinaryEligibilityVector(x, 1, copy(action_preferences))
	return (feature_vector = x, update_feature_vector! = update_feature_vector!, action_preferences = action_preferences, eligibility_vector = ∇lnπ)
end

# ╔═╡ 0e9de19e-bcd4-40ac-9831-afb6cad38422
function setup_fcann_policy_arguments(params::FCANNParams{T}, input_length::Integer, hidden_layers::Vector{Int64}, reslayers::Integer, l2::T, dropout::T, use_μP::Bool, activation_list) where {T<:Real}
	x = zeros(T, input_length)
	activations = FCANN.form_activations(params[1])
	tanh_grad_z = deepcopy(activations)
	deltas = deepcopy(activations)
	scales = fill(one(T), length(params[1]))
	if use_μP
		for i in eachindex(hidden_layers)
			i′ = i + 1
			scales[i′] /= size(params[1][i′], 2)
		end
	end	 

	∇lnπ = deepcopy(params)

	update_eligibility_vector!(∇lnπ::FCANNParams, action_preferences::Vector{T}, x, i_a, params::FCANNParams) = update_fcann_eligibility_vector!(∇lnπ, action_preferences, x, i_a, params, hidden_layers, l2, tanh_grad_z, activations, deltas, dropout, reslayers, activation_list, scales)
	
	update_action_preferences!(action_preferences::Vector{T}, x::Vector{T}, params::FCANNParams) = update_fcann_action_preferences!(action_preferences, x, params, activations, reslayers)

	return (feature_vector = x, params = params, eligibility_vector = ∇lnπ, update_eligibility_vector! = update_eligibility_vector!, update_action_preferences! = update_action_preferences!, scales = scales)
end

