# ╔═╡ 3bafd7df-9bc0-4d13-874d-739590cf3ad9
md"""
> ### *Exercise 13.2*
> Generalize the proof of the policy gradient theorem and the steps leading to the REINFORCE update equation (13.8), so that (13.8) ends up with a factor of $\gamma^t$ and thus aligns with the general algorithm given in the pseudocode.

See proof above in the section on proving the policy gradient theorem.
"""

# ╔═╡ cc45091e-b889-4d5a-9eef-84d80f792046
md"""
## 13.4 REINFORCE with Baseline

The policy gradient theorem (13.5) can be generalized to include a comparison of the action value to an arbitrary *baseline* b(s):

$\nabla J(\mathbf{\theta}) \propto \sum_s \mu(s)\sum_a\left( q_\pi(s,a)-b(s) \right ) \nabla\pi(a|s,\mathbf{\theta}) \tag{13.10}$

The baseline can be any function, even a random variable, as long as it does not vary with $a$; the euation remains valid because the subtracted quantity is zero:

$\sum_ab(s)\nabla\pi(a|s,\mathbf{\theta})=b(s)\nabla\sum_a\pi(a|s,\mathbf{\theta})=b(s)\nabla1=0$

The policy gradient theorem with baseline (13.10) can be used to derive an update rule using similar steps as in the previous section.  The update rule that we end up with is a new version of REINFORCE that includes a general baseline:

$\mathbf{\theta}_{t+1} \doteq \mathbf{\theta}_t+\alpha(G_t-b(S_t))\frac{\nabla\pi(A_t|S_t,\mathbf{\theta}_t)}{\pi(A_t|S_t,\mathbf{\theta}_t)} \tag{13.11}$

Since the baseline could be uniformly zero, this is a strict generalization of REINFORCE.  To have an effective baseline that depends on state we can use a state value estimate that is also updated with gradient steps: $\hat v(S_t, \mathbf{w})$.  Using such an estimate we can revise the previous REINFORCE algorithm.
"""

# ╔═╡ d83dc659-dce7-41dd-a8e7-2933ab39d15c
md"""
### *REINFORCE with Baseline Implementation*

These functions use two sets of parameters, one to calculate the policy function and another to calculate the state value function.  The state representation vector is shared between the two functions, but the policy function will return a distribution of preferences over actions while the value function will return a single value.  If linear approximation is used to estimate both functions, the the policy parameters $\mathbf{\theta}$ will be a $d \times N_a$ matrix where $d$ is the length of the state feature vector representation and the value function parameters $\mathbf{w}$ will be a length $d$ vector.  It is also possible to mix linear and non-linear approximation with this method.
"""

# ╔═╡ 1753b5ed-c00b-4b60-b492-822180778e8c
function update_linear_value_gradient!(∇v̂::Vector{T}, x::Vector{T}, value_params::Vector{T}) where {T<:Real}
	∇v̂ .= x
end

# ╔═╡ 03a218cb-aa83-4000-85b5-c6f247087053
function update_binary_value_gradient!(∇v̂::BinaryFeatureVector, binary_features::BinaryFeatureVector, value_params::Vector{T}) where T<:Real
	∇v̂.active_features = binary_features.active_features
	∇v̂.num_features = binary_features.num_features
end

# ╔═╡ a893a87b-2d07-4db5-9d1a-9da8646216f4
function update_params_with_gradient!(w::Vector{T}, α::T, ∇w::BinaryFeatureVector) where {T<:Real}
	@inbounds @simd for i in 1:∇w.num_features
		j = ∇w.active_features[i]
		w[j] += α
	end
	return w
end

# ╔═╡ 5c4a383f-fcf2-4f2b-819f-6d84471dda00
function update_fcann_value_gradient!(∇v̂::FCANNParams, x::Vector{T}, params::FCANNParams, hidden_layers::Vector{Int64}, l2::T, tanh_grad_z::FCANNActivations{T}, activations::FCANNActivations{T}, deltas::FCANNActivations{T}, dropout::T, reslayers::Integer, activation_list::AbstractVector{B}, scales) where {T<:Float32, B<:Bool}
	FCANN.nnCostFunction(params..., hidden_layers, x, 1, l2, ∇v̂..., tanh_grad_z, activations, deltas, dropout; resLayers = reslayers, loss_type = OutputIndex(), activation_list = activation_list)
	@inbounds for i in eachindex(params[1])
		for j in 1:2
			∇v̂[j][i] .*= scales[i]
		end
	end
end

# ╔═╡ 2cbc972b-c685-4c1c-8a8d-9d58b197ad90
function update_binary_value_params!(params::Vector{T}, active_features::BinaryFeatures, c::T) where T<:Real
	@inbounds for i in active_features
		params[i] += c
	end
	return params
end

# ╔═╡ 77cf3a74-899f-4ade-99f2-5aaf7a98c02d
function scale_fcann_params!(params::FCANNParams, scales::Vector{T}) where T<:Real
	@inbounds for i in eachindex(scales)
		for j in 1:2
			params[j][i] ./= scales[i]
		end
	end
end

# ╔═╡ 0bf3b988-b3fb-49d5-8dde-b25766596363
linear_value_function(x::Vector{T}, w::Vector{T}) where {T<:Real} = dot(x, w)

# ╔═╡ a540814a-57a1-4b98-9443-59e401425444
function binary_value_function(binary_features::BinaryFeatureVector, params::Vector{T})::T where T<:Real
	v = zero(T)
	@inbounds @simd for i in 1:binary_features.num_features
		j = binary_features.active_features[i]
		v += params[j]
	end
	return v
end

# ╔═╡ 635abb34-2c97-4f04-a74c-22fbec32f408
function fcann_value_function(x::Vector{T}, params::FCANNParams, activations::FCANNActivations{T}, reslayers::Integer) where T<:Float32
	FCANN.forwardNOGRAD_base!(activations, params..., x, reslayers)
	return first(last(activations))
end

# ╔═╡ 37ec6802-d4c2-4470-ad69-439d5a732f77
function form_state_policy_function(update_feature_vector!::Function, update_action_preferences!::Function)
	function π!(x, action_preferences, s, params)
		update_feature_vector!(x, s)
		update_action_preferences!(action_preferences, x, params)
		soft_max!(action_preferences)
	end
end

# ╔═╡ e7566274-5518-4e28-8738-d4b1747d0cfb
function form_state_value_function(update_feature_vector!::Function, value_function::Function)
	function v!(x, s, value_params)
		update_feature_vector!(x, s)
		value_function(x, value_params)
	end
end

# ╔═╡ f3e2db06-9cb7-464a-96b8-938175efd26b
function setup_fcann_value_arguments(policy_setup::NamedTuple, input_length::Integer, hidden_layers::Vector{Int64}, reslayers::Integer, l2::T, dropout::T, use_μP::Bool, activation_list, scales) where {T<:Real}
	scale = (reslayers == 0) ? 1 : length(hidden_layers)/(reslayers + 1) + 1
	c = scale*last(hidden_layers)
	f = use_μP ? one(T) / c : c^T(-0.5)
	w_θ_out = T.(FCANN.makeorthonormalrand(1, last(hidden_layers)) .* f)
	w_β_out = zeros(T, 1)

		
	#value function shares its params with the policy function
	value_params = deepcopy(policy_setup.params)
	for i in eachindex(hidden_layers)
		for j in 1:2
			value_params[j][i] = policy_setup.params[j][i]
		end
	end
	
	#replace the final layer of the value network with something that outputs a single value
	value_params[1][end] = w_θ_out
	value_params[2][end] = w_β_out

	# value_params = FCANN.initializeparams_saxe(input_length, hidden_layers, 1)

	#form activations for value network
	value_activations = FCANN.form_activations(value_params[1])
	value_activations[end] = zeros(T, 1)
	value_tanh_grad_z = deepcopy(value_activations)
	value_deltas = deepcopy(value_activations)
		
	value_function(x, params) = fcann_value_function(x, params, value_activations, reslayers)
	function update_value_gradient!(∇v̂, x, value_params) 
		update_fcann_value_gradient!(∇v̂, x, value_params, hidden_layers, l2, value_tanh_grad_z, value_activations, value_deltas, dropout, reslayers, activation_list, scales)
		use_μP && scale_fcann_params!(∇v̂, policy_setup.scales)
	end

	return (value_params = value_params, value_gradient = deepcopy(value_params), value_function = value_function, gradient_update = update_value_gradient!)
end

# ╔═╡ e1aec891-d95a-47d1-97d7-d2a4cfb16e64
function setup_fcann_policy_and_value_arguments(policy_params::FCANNParams{T}, input_length::Integer, hidden_layers::Vector{Int64}, reslayers::Integer, l2::T, dropout::T, use_μP::Bool, activation_list) where {T<:Real}
	policy_setup = setup_fcann_policy_arguments(policy_params::FCANNParams{T}, input_length::Integer, hidden_layers::Vector{Int64}, reslayers::Integer, l2::T, dropout::T, use_μP::Bool, activation_list)
	value_setup = setup_fcann_value_arguments(policy_setup, input_length::Integer, hidden_layers::Vector{Int64}, reslayers::Integer, l2::T, dropout::T, use_μP::Bool, activation_list, policy_setup.scales)
	(;policy_setup..., value_setup...)
end

